# ---- dchrgscrt
FF = '( k e. %s |-> %s )' % (FU, f('k')); GG = '( k e. %s |-> %s )' % (FV, g('k'))
A0 = HCRT0
Aa = '( %s /\\ a e. %s )' % (A0, S)
