s1 = w.s([w.s([lem, w.s([w.s([ffv, ggv], 'oveq12d', '( %s -> %s = ( %s x. %s ) )' % (Aa, T1, f(AMU), g(AMV)))], 'eqcomd', '( %s -> ( %s x. %s ) = %s )' % (Aa, f(AMU), g(AMV), T1))], 'eqtrd', '( %s -> %s = %s )' % (Aa, LHS, T1))], 'sumeq2dv', '( %s -> %s = sum_ a e. %s %s )' % (A0, GRUV, S, T1))
