fc = w.s([w.s([u, v, cop], '3jca', '( %s -> %s )' % (A0, HCRT)), w.s([ffn, ggn], 'jca', '( %s -> ( %s : %s --> CC /\\ %s : %s --> CC ) )' % (A0, FF, FU, GG, FV)), w.inst('fsumcrt')], 'syl2anc', '( %s -> sum_ a e. %s %s = ( sum_ b e. %s ( %s ` b ) x. sum_ c e. %s ( %s ` c ) ) )' % (A0, S, T1, FU, FF, FV, GG))
# ( FF ` b ) = f ( b ), ( GG ` c ) = g ( c )
